ency=1,Position=UDim2.fromOffset(24,146),Size=UDim2.new(1, -48,0,18),TextXAlignment=Enum.TextXAlignment.Left,Parent=main});local function makeButton(text,xScale,xOffset,filled) local btn=new("TextButton",{Text=text,Font=Enum.Font.GothamBold,TextSize=15,TextColor3=Color3.new(1,1,1),BackgroundColor3=(filled and Color3.new(1,1,1)) or Color3.fromRGB(24,24,36) ,Size=UDim2.new(0.5, -30,0,46),Position=UDim2.new(xScale,xOffset,0,178),AutoButtonColor=false,BorderSizePixel=0,Parent=main},{corner(10)});if filled then btn:FindFirstChildOfClass("UICorner").Parent=btn;gradient(CONFIG.Accent,CONFIG.Accent2,20).Parent=btn;else stroke(CONFIG.Accent,1.5,0.2).Parent=btn;end btn.MouseEnter:Connect(function() tween(btn,0.15,{Size=UDim2.new(0.5, -26,0,48),Position=UDim2.new(xScale,xOffset-2 ,0,177)});end);btn.MouseLeave:Connect(function() tween(btn,0.15,{Size=UDim2.new(0.5, -30,0,46),Position=UDim2.new(xScale,xOffset,0,178)});end);return btn;end local checkBtn=makeButton("Check Key",0,24,true);local copyBtn=makeButton("Copy Link",0.5,6,false);local function setStatus(text,color) status.Text=text;status.TextColor3=color;end local function flashInput(color) tween(inputStroke,0.15,{Color=color});task.delay(0.8,function() tween(inputStroke,0.3,{Color=Color3.fromRGB(50,50,70)});end);end local function shake() local base=main.Position;for _=1,3 do tween(main,0.04,{Position=base + UDim2.fromOffset(8,0) }).Completed:Wait();tween(main,0.04,{Position=base-UDim2.fromOffset(8,0) }).Completed:Wait();end tween(main,0.04,{Position=base});end local function closeGui() tween(main,0.25,{Size=UDim2.fromOffset(400,0)});tween(glow,0.25,{BackgroundTransparency=1});task.wait(0.3);gui:Destroy();end keyBox.Focused:Connect(function() tween(inputStroke,0.15,{Color=CONFIG.Accent});end);keyBox.FocusLost:Connect(function() tween(inputStroke,0.15,{Color=Color3.fromRGB(50,50,70)});end);local busy=false;checkBtn.MouseButton1Click:Connect(function() if busy then return;end busy=true;local entered=keyBox.Text:gsub("^%s+",""):gsub("%s+$","");if (entered=="") then setStatus("Please enter a key.",Color3.fromRGB(255,190,80));flashInput(Color3.fromRGB(255,190,80));elseif (entered==CONFIG.Key) then setStatus("Key valid! Loading...",Color3.fromRGB(80,230,140));flashInput(Color3.fromRGB(80,230,140));task.wait(0.8);closeGui();LoadMainScript();return;else setStatus("Invalid key. Get one with 'Copy Link'.",Color3.fromRGB(255,90,100));flashInput(Color3.fromRGB(255,90,100));shake();end busy=false;end);copyBtn.MouseButton1Click:Connect(function() if copyToClipboard(CONFIG.Link) then setStatus("Link copied to clipboard!",Color3.fromRGB(80,230,140));copyBtn.Text="Copied!";task.delay(1.5,function() if copyBtn then copyBtn.Text="Copy Link";end end);else setStatus("Clipboard not supported: "   .. CONFIG.Link ,Color3.fromRGB(255,190,80));end end);close.MouseEnter:Connect(function() tween(close,0.15,{BackgroundColor3=Color3.fromRGB(200,60,80)});end);close.MouseLeave:Connect(function() tween(close,0.15,{BackgroundColor3=Color3.fromRGB(30,30,42)});end);close.MouseButton1Click:Connect(closeGui);do local dragging,dragStart,startPos;main.InputBegan:Connect(function(input) if ((input.UserInputType==Enum.UserInputType.MouseButton1) or (input.UserInputType==Enum.UserInputType.Touch)) then dragging,dragStart,startPos=true,input.Position,main.Position;input.Changed:Connect(function() if (input.UserInputState==Enum.UserInputState.End) then dragging=false;end end);end end);UserInputService.InputChanged:Connect(function(input) if (dragging and ((input.UserInputType==Enum.UserInputType.MouseMovement) or (input.UserInputType==Enum.UserInputType.Touch))) then local d=input.Position-dragStart ;local pos=UDim2.new(startPos.X.Scale,startPos.X.Offset + d.X ,startPos.Y.Scale,startPos.Y.Offset + d.Y );main.Position=pos;glow.Position=pos;end end);end main.Size=UDim2.fromOffset(400,0);glow.BackgroundTransparency=1;tween(main,0.4,{Size=UDim2.fromOffset(400,250)});tween(glow,0.4,{BackgroundTransparency=0.82}); end